pages.blockStyle:
.modelBarCustom {
overflow: hidden;
}
.modelBarCustom .nav-tabs {
border-bottom: 0;
position: relative;
}
.modelBarCustom .nav-tabs>li>a {
background-color: transparent;
}
.modelBarCustom .nav-tabs>li>a:hover {
border-color: transparent;
}
.modelBarCustom .nav-tabs>li.active>a,
.modelBarCustom .nav-tabs>li.active>a:hover,
.modelBarCustom .nav-tabs>li.active>a:focus {
background-color: transparent;
border-color: transparent;
}
.modelBarCustom .logoTab:not(.active) .logoOEM {
opacity: 1;
margin-bottom: 15px;
}
.modelBarCustom .logoTab.active {
opacity: 1;
}
.modelBarCustom .fa-caret-up {
bottom: 12px;
left: 0;
line-height: 0;
opacity: 0;
position: absolute;
right: 0;
transform: translateX(13%);
}
.modelBarCustom .logoTab.active .fa-caret-up {
opacity: 1;
}
/* Model Bar Indicator */
.modelBarCustom #modelBarIndicator {
opacity: 1 !important;
}
#modelBarIndicator.indicatorSlide1 {
transform: translateX(-37%);
}
#modelBarIndicator.indicatorSlide2 {
transform: translateX(-13%);
}
#modelBarIndicator.indicatorSlide3 {
transform: translateX(13%);
}
#modelBarIndicator.indicatorSlide4 {
transform: translateX(37.5%);
}
#modelBarIndicator,
#cdjr-model-bar .tab-pane.active,
#cdjr-model-bar .fade {
transition-timing-function: ease-in;
-webkit-transition-duration: 0.25s;
-moz-transition-duration: 0.25s;
-o-transition-duration: 0.25s;
transition-duration: 0.25s;
/* -webkit-backface-visibility: hidden;
backface-visibility: hidden; */
}
.modelBarS .carImage {
transition-timing-function: ease-in;
-webkit-transition-duration: 0.1s;
-moz-transition-duration: 0.1s;
-o-transition-duration: 0.1s;
transition-duration: 0.1s;
padding: 0 10px;
}
.modelBarS .carImage:hover {
-moz-transform: scale(1.1);
-webkit-transform: scale(1.1);
transform: scale(1.1);
}
.modelBarS {
display: none;
opacity: 0;
visibility: hidden;
transition: opacity 1s ease;
-webkit-transition: opacity 1s ease;
padding: 40px 0;
}
.modelBarS.slick-initialized {
visibility: visible;
opacity: 1;
}
.modelBarS .slick-list {
margin: 0 45px;
}
.slick-prev::before,
.slick-next::before {
opacity: 0.65;
color: #707070;
transition: all 250ms ease-in-out;
}
/* bootstrap hack: fix content width inside hidden tabs */
.modelBarSec .tab-content>.tab-pane,
.modelBarSec .pill-content>.pill-pane {
display: block;
height: 0;
overflow-y: hidden;
}
.modelBarSec .tab-content>.active,
.modelBarSec .pill-content>.active {
height: auto;
}
/* end bootstrap hack */

