@media (min-width: 768px) {
.vehicleModels .nav>li a: : after {
background: #CB0000; bottom: 0; content: ""; display: block; left: 50%; height: 2px; opacity: .1; filter: alpha(opacity=10); position: absolute; transition: width .15s cubic-bezier(.215, .61, .355, 1), left .15s cubic-bezier(.215, .61, .355, 1), opacity .2s cubic-bezier(.215, .61, .355, 1); width: .5%;
}
.vehicleModels .nav>li.active a::after,
.vehicleModels .nav>li a:hover::after {
