color: #333; font-size: 1.2em;
}
.vehicleModels .nav>li {
position: relative; display: inline-block;
}
.vehicleModels .tab-content:hover .vehicleModelsItem:not(:hover) {
opacity: 0.5; transition: opacity .3s;
}
}
